// ASK 227 rev 2: the HTTP node emits one item PER ROW (execution 36577), so rows come from every input item.
// The two older shapes (the whole array as one item, or an object with one key holding it) are still accepted.
const ins = $input.all().map(i => i.json);
let rows = [];
if (ins.length === 1 && Array.isArray(ins[0])) {
  rows = ins[0];
} else if (ins.length === 1 && ins[0] && typeof ins[0] === 'object' && !('table_name' in ins[0]) && Object.keys(ins[0]).length === 1) {
  rows = ins[0][Object.keys(ins[0])[0]] || [];
} else {
  rows = ins.filter(r => r && typeof r === 'object' && typeof r.table_name === 'string');
}
if (!rows || rows.length === 0) return [];
const grouped = {};
rows.forEach(r => {
  if (!grouped[r.table_name]) grouped[r.table_name] = [];
  grouped[r.table_name].push(r);
});
return Object.entries(grouped).map(([tableName, tableRows]) => ({
  json: {
    table_name: tableName,
    row_count: tableRows.length,
    rows: tableRows,
    snapshot_ts: new Date().toISOString()
  }
}));

// ASK 227: one file per table group. The RPC marks every fetched row exported, so every group must be written.
return $input.all().map(item => {
const d = item.json;
const ts = d.snapshot_ts;
const tableName = d.table_name;
let content = '# TRUTH App — Table Snapshot\n';
content += '## Table: ' + tableName + '\n';
content += '## Snapshot Time: ' + ts + '\n';
content += '## Change Count: ' + d.row_count + '\n';
content += '## Protected Table: YES — training knowledge target\n\n---\n\n';
d.rows.forEach((r, i) => {
  content += '### Change ' + (i+1) + ' — ' + r.operation + ' at ' + r.triggered_at + '\n';
  content += '```json\n' + JSON.stringify(r.changed_row, null, 2) + '\n```\n\n';
});
const filename = 'Snapshot_' + tableName + '_' + ts.replace(/[:.]/g, '-').replace('T', '_').substring(0, 19) + '.md';
// ASK 228: carry the queue ids so a file Drive refuses can be set back to pending.
return { json: { content, filename, table_name: tableName, snapshot_ts: ts, export_ids: d.rows.map(r => r.id) } };
});

const built = $('Build Snapshot Content').all().map(x => x.json);
// ASK 228: the save nodes continue on a refused file, so count only items carrying a Drive file id.
const out = $input.all().map(x => x.json || {});
const saved = out.filter(j => typeof j.id === 'string' && j.id.length > 0).length;
return [{ json: { status: saved === out.length ? 'snapshot_saved' : 'snapshot_partial', path: $prevNode.name, tables: built.map(b => b.table_name), files: built.map(b => b.filename), saved, refused: out.length - saved, of: built.length, ts: new Date().toISOString() } }];

// ASK 228: the save node continues on a refused file. The Google Drive v2 router pushes exactly one item per input file, in order:
// { id } when Drive created the file, { error: <message> } when Drive refused it (n8n-nodes-base 2.15.1). So save output k is
// Build Snapshot Content item k. Only the refused files go on, through the 62 s wait, to the retry; none refused ends this branch.
const built = $('Build Snapshot Content').all().map(x => x.json);
const out = $input.all().map(x => x.json || {});
const savedAt = k => typeof out[k].id === 'string' && out[k].id.length > 0;
if (out.length !== built.length) {
  // Not the shape the router produces: send every file again. A duplicate file is acceptable, a lost batch is not.
  return built.map(b => ({ json: { ...b, first_error: 'save returned ' + out.length + ' items for ' + built.length + ' files' } }));
}
return built.map((b, k) => ({ b, k })).filter(x => !savedAt(x.k))
  .map(x => ({ json: { ...x.b, first_error: String(out[x.k].error || 'no file id returned').slice(0, 300) } }));

// pkgPTR rev 3: the retry continues on a refused file and returns one item per file, in order. The files it refused go on to a
// name search (Find Landed Files (retry)); Confirm Unsaved Rows re-queues only those not found. None refused ends this branch.
const sent = $('Drop Landed Files').all().map(x => x.json);
const out = $input.all().map(x => x.json || {});
const lost = out.length !== sent.length ? sent : sent.filter((b, k) => !(typeof out[k].id === 'string' && out[k].id.length > 0));
if (lost.length === 0) return [];
const e = out.find(j => j && j.error);
const error = String((e && e.error) || (out.length !== sent.length ? 'retry returned ' + out.length + ' items for ' + sent.length + ' files' : 'no file id returned')).slice(0, 300);
return [{ json: { lost: lost.map(b => ({ filename: b.filename, table_name: b.table_name, export_ids: b.export_ids })), error } }];

// pkgPTR rev 3: a save item reported refused can still have created its file (the upload is a POST, then a PATCH; a 403 on the
// PATCH comes after the file exists). Every refused file whose exact name the search found in the folder is left out of the retry.
// A refused or unreadable search sends every refused file again, as rev 2 did: a duplicate file is acceptable, a lost batch is not.
const sent = $('Wait Out Drive Quota').all().map(x => x.json);
const res = $input.all().map(x => x.json || {});
const e = res.find(j => j && j.error);
const found = new Set(e ? [] : res.filter(j => typeof j.id === 'string' && j.id.length > 0 && typeof j.name === 'string').map(j => j.name));
const search = e ? 'search refused: ' + String(e.error).slice(0, 200) : 'searched: ' + found.size + ' of ' + sent.length + ' already in the folder';
return sent.filter(b => !found.has(b.filename)).map(b => ({ json: { ...b, search } }));

// pkgPTR rev 3: a file the retry reported refused but whose name is in the folder landed; its rows stay exported. The rest have
// their rows set back to pending, because get_pending_snapshots already marked them exported. A refused search re-queues them all.
const c = $('Collect Unsaved Rows').first().json;
const res = $input.all().map(x => x.json || {});
const e = res.find(j => j && j.error);
const found = new Set(e ? [] : res.filter(j => typeof j.id === 'string' && j.id.length > 0 && typeof j.name === 'string').map(j => j.name));
const lost = c.lost.filter(b => !found.has(b.filename));
if (lost.length === 0) return [];
const ids = [...new Set(lost.flatMap(b => Array.isArray(b.export_ids) ? b.export_ids : []))].filter(v => Number.isInteger(v) && v > 0);
if (ids.length === 0) throw new Error('PROTECTED SNAPSHOT: Drive refused ' + lost.length + ' file(s) twice and no queue ids were found to re-queue. Rows stay marked exported: ' + lost.map(b => b.filename).join(', '));
const search = e ? 'search refused: ' + String(e.error).slice(0, 200) : 'searched: ' + (c.lost.length - lost.length) + ' of ' + c.lost.length + ' already in the folder';
return [{ json: { ids, files: lost.map(b => b.filename), tables: lost.map(b => b.table_name), error: c.error, search } }];

